     1→#!/usr/bin/env node
     2→
     3→import { spawn, ChildProcess } from "child_process";
     4→import * as path from "path";
     5→import * as fs from "fs";
     6→import { HTMLGenerator } from "./html-generator";
     7→
     8→// Colors for output
     9→export const colors = {
    10→	red: "\x1b[0;31m",
    11→	green: "\x1b[0;32m",
    12→	yellow: "\x1b[1;33m",
    13→	blue: "\x1b[0;34m",
    14→	reset: "\x1b[0m",
    15→} as const;
    16→
    17→type ColorName = keyof typeof colors;
    18→
    19→function log(message: string, color: ColorName = "reset"): void {
    20→	console.log(`${colors[color]}${message}${colors.reset}`);
    21→}
    22→
    23→function showHelp(): void {
    24→	console.log(`
    25→${colors.blue}Claude Trace${colors.reset}
    26→Record all your interactions with Claude Code as you develop your projects
    27→
    28→${colors.yellow}USAGE:${colors.reset}
    29→  claude-trace [OPTIONS] [--run-with CLAUDE_ARG...]
    30→
    31→${colors.yellow}OPTIONS:${colors.reset}
    32→  --extract-token    Extract OAuth token and exit (reproduces claude-token.py)
    33→  --generate-html    Generate HTML report from JSONL file
    34→  --index           Generate conversation summaries and index for .claude-trace/ directory
    35→  --run-with         Pass all following arguments to Claude process
    36→  --include-all-requests Include all requests made through fetch, otherwise only requests to v1/messages with more than 2 messages in the context
    37→  --no-open          Don't open generated HTML file in browser
    38→  --log              Specify custom log file base name (without extension)
    39→  --claude-path      Specify custom path to Claude binary
    40→  --help, -h         Show this help message
    41→
    42→${colors.yellow}MODES:${colors.reset}
    43→  ${colors.green}Interactive logging:${colors.reset}
    44→    claude-trace                               Start Claude with traffic logging
    45→    claude-trace --log my-session              Start Claude with custom log file name
    46→    claude-trace --run-with chat                    Run Claude with specific command
    47→    claude-trace --run-with chat --model sonnet-3.5 Run Claude with multiple arguments
    48→
    49→  ${colors.green}Token extraction:${colors.reset}
    50→    claude-trace --extract-token               Extract OAuth token for SDK usage
    51→
    52→  ${colors.green}HTML generation:${colors.reset}
    53→    claude-trace --generate-html file.jsonl          Generate HTML from JSONL file
    54→    claude-trace --generate-html file.jsonl out.html Generate HTML with custom output name
    55→    claude-trace --generate-html file.jsonl          Generate HTML and open in browser (default)
    56→    claude-trace --generate-html file.jsonl --no-open Generate HTML without opening browser
    57→
    58→  ${colors.green}Indexing:${colors.reset}
    59→    claude-trace --index                             Generate conversation summaries and index
    60→
    61→${colors.yellow}EXAMPLES:${colors.reset}
    62→  # Start Claude with logging
    63→  claude-trace
    64→
    65→  # Start Claude with custom log file name
    66→  claude-trace --log my-session
    67→
    68→  # Run Claude chat with logging
    69→  claude-trace --run-with chat
    70→
    71→  # Run Claude with specific model
    72→  claude-trace --run-with chat --model sonnet-3.5
    73→
    74→  # Pass multiple arguments to Claude
    75→  claude-trace --run-with --model gpt-4o --temperature 0.7
    76→
    77→  # Extract token for Anthropic SDK
    78→  export ANTHROPIC_API_KEY=$(claude-trace --extract-token)
    79→
    80→  # Generate HTML report
    81→  claude-trace --generate-html logs/traffic.jsonl report.html
    82→
    83→  # Generate HTML report and open in browser (default)
    84→  claude-trace --generate-html logs/traffic.jsonl
    85→
    86→  # Generate HTML report without opening browser
    87→  claude-trace --generate-html logs/traffic.jsonl --no-open
    88→
    89→  # Generate conversation index
    90→  claude-trace --index
    91→
    92→  # Use custom Claude binary path
    93→  claude-trace --claude-path /usr/local/bin/claude
    94→
    95→${colors.yellow}OUTPUT:${colors.reset}
    96→  Logs are saved to: ${colors.green}.claude-trace/log-YYYY-MM-DD-HH-MM-SS.{jsonl,html}${colors.reset}
    97→  With --log NAME:   ${colors.green}.claude-trace/NAME.{jsonl,html}${colors.reset}
    98→
    99→${colors.yellow}MIGRATION:${colors.reset}
   100→  This tool replaces Python-based claude-logger and claude-token.py scripts
   101→  with a pure Node.js implementation. All output formats are compatible.
   102→
   103→For more information, visit: https://github.com/mariozechner/claude-trace
   104→`);
   105→}
   106→
   107→function resolveToJsFile(filePath: string): string {
   108→	try {
   109→		// First, resolve any symlinks
   110→		const realPath = fs.realpathSync(filePath);
   111→
   112→		// Check if it's already a JS file
   113→		if (realPath.endsWith(".js")) {
   114→			return realPath;
   115→		}
   116→
   117→		// If it's a Node.js shebang script, check if it's actually a JS file
   118→		if (fs.existsSync(realPath)) {
   119→			const content = fs.readFileSync(realPath, "utf-8");
   120→			// Check for Node.js shebang
   121→			if (
   122→				content.startsWith("#!/usr/bin/env node") ||
   123→				content.match(/^#!.*\/node$/m) ||
   124→				content.includes("require(") ||
   125→				content.includes("import ")
   126→			) {
   127→				// This is likely a JS file without .js extension
   128→				return realPath;
   129→			}
   130→		}
   131→
   132→		// If not a JS file, try common JS file locations
   133→		const possibleJsPaths = [
   134→			realPath + ".js",
   135→			realPath.replace(/\/bin\//, "/lib/") + ".js",
   136→			realPath.replace(/\/\.bin\//, "/lib/bin/") + ".js",
   137→		];
   138→
   139→		for (const jsPath of possibleJsPaths) {
   140→			if (fs.existsSync(jsPath)) {
   141→				return jsPath;
   142→			}
   143→		}
   144→
   145→		// Fall back to original path
   146→		return realPath;
   147→	} catch (error) {
   148→		// If resolution fails, return original path
   149→		return filePath;
   150→	}
   151→}
   152→
   153→function getClaudeAbsolutePath(customPath?: string): string {
   154→	// If custom path is provided, use it directly
   155→	if (customPath) {
   156→		if (!fs.existsSync(customPath)) {
   157→			log(`Claude binary not found at specified path: ${customPath}`, "red");
   158→			process.exit(1);
   159→		}
   160→		return resolveToJsFile(customPath);
   161→	}
   162→
   163→	try {
   164→		let claudePath = require("child_process")
   165→			.execSync("which claude", {
   166→				encoding: "utf-8",
   167→			})
   168→			.trim();
   169→
   170→		// Handle shell aliases (e.g., "claude: aliased to /path/to/claude")
   171→		const aliasMatch = claudePath.match(/:\s*aliased to\s+(.+)$/);
   172→		if (aliasMatch && aliasMatch[1]) {
   173→			claudePath = aliasMatch[1];
   174→		}
   175→
   176→		// Check if the path is a bash wrapper
   177→		if (fs.existsSync(claudePath)) {
   178→			const content = fs.readFileSync(claudePath, "utf-8");
   179→			if (content.startsWith("#!/bin/bash")) {
   180→				// Parse bash wrapper to find actual executable
   181→				const execMatch = content.match(/exec\s+"([^"]+)"/);
   182→				if (execMatch && execMatch[1]) {
   183→					const actualPath = execMatch[1];
   184→					// Resolve any symlinks to get the final JS file
   185→					return resolveToJsFile(actualPath);
   186→				}
   187→			}
   188→		}
   189→
   190→		return resolveToJsFile(claudePath);
   191→	} catch (error) {
   192→		// First try the local bash wrapper
   193→		const os = require("os");
   194→		const localClaudeWrapper = path.join(os.homedir(), ".claude", "local", "claude");
   195→
   196→		if (fs.existsSync(localClaudeWrapper)) {
   197→			const content = fs.readFileSync(localClaudeWrapper, "utf-8");
   198→			if (content.startsWith("#!/bin/bash")) {
   199→				const execMatch = content.match(/exec\s+"([^"]+)"/);
   200→				if (execMatch && execMatch[1]) {
   201→					return resolveToJsFile(execMatch[1]);
   202→				}
   203→			}
   204→		}
   205→
   206→		// Then try the node_modules/.bin path
   207→		const localClaudePath = path.join(os.homedir(), ".claude", "local", "node_modules", ".bin", "claude");
   208→		if (fs.existsSync(localClaudePath)) {
   209→			return resolveToJsFile(localClaudePath);
   210→		}
   211→
   212→		log(`Claude CLI not found in PATH`, "red");
   213→		log(`Also checked for local installation at: ${localClaudeWrapper}`, "red");
   214→		log(`Please install Claude Code CLI first`, "red");
   215→		process.exit(1);
   216→	}
   217→}
