   306→// Scenario 2: --extract-token -> launch node with token interceptor and absolute path to claude
   307→async function extractToken(customClaudePath?: string): Promise<void> {
   308→	const claudePath = getClaudeAbsolutePath(customClaudePath);
   309→
   310→	// Log to stderr so it doesn't interfere with token output
   311→	console.error(`Using Claude binary: ${claudePath}`);
   312→
   313→	// Create .claude-trace directory if it doesn't exist
   314→	const claudeTraceDir = path.join(process.cwd(), ".claude-trace");
   315→	if (!fs.existsSync(claudeTraceDir)) {
   316→		fs.mkdirSync(claudeTraceDir, { recursive: true });
   317→	}
   318→
   319→	// Token file location
   320→	const tokenFile = path.join(claudeTraceDir, "token.txt");
   321→
   322→	// Use the token extractor directly without copying
   323→	const tokenExtractorPath = path.join(__dirname, "token-extractor.js");
   324→	if (!fs.existsSync(tokenExtractorPath)) {
   325→		log(`Token extractor not found at: ${tokenExtractorPath}`, "red");
   326→		process.exit(1);
   327→	}
   328→
   329→	const cleanup = () => {
   330→		try {
   331→			if (fs.existsSync(tokenFile)) fs.unlinkSync(tokenFile);
   332→		} catch (e) {
   333→			// Ignore cleanup errors
   334→		}
   335→	};
   336→
   337→	// Launch node with token interceptor and absolute path to claude
   338→	const { ANTHROPIC_API_KEY, ...envWithoutApiKey } = process.env;
   339→	const child: ChildProcess = spawn("node", ["--require", tokenExtractorPath, claudePath, "-p", "hello"], {
   340→		env: {
   341→			...envWithoutApiKey,
   342→			NODE_TLS_REJECT_UNAUTHORIZED: "0",
   343→			CLAUDE_TRACE_TOKEN_FILE: tokenFile,
   344→		},
   345→		stdio: "inherit", // Suppress all output from Claude
   346→		cwd: process.cwd(),
   347→	});
   348→
   349→	// Set a timeout to avoid hanging
   350→	const timeout = setTimeout(() => {
   351→		child.kill();
   352→		cleanup();
   353→		console.error("Timeout: No token found within 30 seconds");
   354→		process.exit(1);
   355→	}, 30000);
   356→
   357→	// Handle child process events
   358→	child.on("error", (error: Error) => {
   359→		clearTimeout(timeout);
   360→		cleanup();
   361→		console.error(`Error starting Claude: ${error.message}`);
   362→		process.exit(1);
   363→	});
   364→
   365→	child.on("exit", () => {
   366→		clearTimeout(timeout);
   367→
   368→		try {
   369→			if (fs.existsSync(tokenFile)) {
   370→				const token = fs.readFileSync(tokenFile, "utf-8").trim();
   371→				cleanup();
   372→				if (token) {
   373→					// Only output the token, nothing else
   374→					console.log(token);
   375→					process.exit(0);
   376→				}
   377→			}
   378→		} catch (e) {
   379→			// File doesn't exist or read error
   380→		}
   381→
   382→		cleanup();
   383→		console.error("No authorization token found");
   384→		process.exit(1);
   385→	});
   386→
   387→	// Check for token file periodically
   388→	const checkToken = setInterval(() => {
   389→		try {
   390→			if (fs.existsSync(tokenFile)) {
   391→				const token = fs.readFileSync(tokenFile, "utf-8").trim();
   392→				if (token) {
   393→					clearTimeout(timeout);
   394→					clearInterval(checkToken);
   395→					child.kill();
   396→					cleanup();
   397→
   398→					// Only output the token, nothing else
   399→					console.log(token);
   400→					process.exit(0);
   401→				}
   402→			}
   403→		} catch (e) {
   404→			// Ignore read errors, keep trying
   405→		}
   406→	}, 500);
   407→}
