   418→		const finalOutputFile = await htmlGenerator.generateHTMLFromJSONL(inputFile, outputFile, includeAllRequests);
   419→
   420→		if (openInBrowser) {
   421→			spawn("open", [finalOutputFile], { detached: true, stdio: "ignore" }).unref();
   422→			log(`Opening ${finalOutputFile} in browser`, "green");
