    94→		];
    95→
    96→		for (const key of Object.keys(redactedHeaders)) {
    97→			const lowerKey = key.toLowerCase();
    98→			if (sensitiveKeys.some((sensitive) => lowerKey.includes(sensitive))) {
    99→				// Keep first 10 chars and last 4 chars, redact middle
   100→				const value = redactedHeaders[key];
   101→				if (value && value.length > 14) {
   102→					redactedHeaders[key] = `${value.substring(0, 10)}...${value.slice(-4)}`;
   103→				} else if (value && value.length > 4) {
   104→					redactedHeaders[key] = `${value.substring(0, 2)}...${value.slice(-2)}`;
   105→				} else {
   106→					redactedHeaders[key] = "[REDACTED]";
   107→				}
   108→			}
   109→		}
   110→
   111→		return redactedHeaders;
   112→	}
   113→
   114→	private async cloneResponse(response: Response): Promise<Response> {
   115→		// Clone the response to avoid consuming the body
   116→		return response.clone();
   117→	}
   118→
   119→	private async parseRequestBody(body: any): Promise<any> {
   120→		if (!body) return null;
   121→
   122→		if (typeof body === "string") {
   123→			try {
   124→				return JSON.parse(body);
   125→			} catch {
   126→				return body;
   127→			}
   128→		}
   129→
   130→		if (body instanceof FormData) {
   131→			const formObject: Record<string, any> = {};
   132→			for (const [key, value] of body.entries()) {
   133→				formObject[key] = value;
   134→			}
   135→			return formObject;
   136→		}
   137→
   138→		return body;
   139→	}
   140→
   141→	private async parseResponseBody(response: Response): Promise<{ body?: any; body_raw?: string }> {
   142→		const contentType = response.headers.get("content-type") || "";
   143→
   144→		try {
   145→			if (contentType.includes("application/json")) {
   146→				const body = await response.json();
   147→				return { body };
   148→			} else if (contentType.includes("text/event-stream")) {
   149→				const body_raw = await response.text();
   150→				return { body_raw };
   151→			} else if (contentType.includes("text/")) {
   152→				const body_raw = await response.text();
   153→				return { body_raw };
   154→			} else {
   155→				// For other types, try to read as text
   156→				const body_raw = await response.text();
   157→				return { body_raw };
   158→			}
   159→		} catch (error) {
   160→			// Silent error handling during runtime
   161→			return {};
   162→		}
   163→	}
   164→
   165→	public instrumentAll(): void {
   166→		this.instrumentFetch();
   167→		this.instrumentNodeHTTP();
   168→	}
   169→
   170→	public instrumentFetch(): void {
   171→		if (!global.fetch) {
   172→			// Silent - fetch not available
   173→			return;
   174→		}
   175→
   176→		// Check if already instrumented by checking for our marker
   177→		if ((global.fetch as any).__claudeTraceInstrumented) {
   178→			return;
   179→		}
   180→
   181→		const originalFetch = global.fetch;
   182→		const logger = this;
   183→
   184→		global.fetch = async function (input: RequestInfo | URL, init: RequestInit = {}): Promise<Response> {
   185→			// Convert input to URL for consistency
   186→			const url = typeof input === "string" ? input : input instanceof URL ? input.toString() : input.url;
   187→
   188→			// Only intercept Claude API calls
   189→			if (!logger.isClaudeAPI(url)) {
   190→				return originalFetch(input, init);
   191→			}
   192→
   193→			const requestId = logger.generateRequestId();
   194→			const requestTimestamp = Date.now();
   195→
   196→			// Capture request details
   197→			const requestData = {
   198→				timestamp: requestTimestamp / 1000, // Convert to seconds (like Python version)
   199→				method: init.method || "GET",
   200→				url: url,
   201→				headers: logger.redactSensitiveHeaders(Object.fromEntries(new Headers(init.headers || {}).entries())),
   202→				body: await logger.parseRequestBody(init.body),
   203→			};
   204→
   205→			// Store pending request
   206→			logger.pendingRequests.set(requestId, requestData);
   207→
   208→			try {
   209→				// Make the actual request
   210→				const response = await originalFetch(input, init);
   211→				const responseTimestamp = Date.now();
   212→
   213→				// Clone response to avoid consuming the body
   214→				const clonedResponse = await logger.cloneResponse(response);
   215→
   216→				// Parse response body
   217→				const responseBodyData = await logger.parseResponseBody(clonedResponse);
   218→
   219→				// Create response data
   220→				const responseData = {
   221→					timestamp: responseTimestamp / 1000,
   222→					status_code: response.status,
   223→					headers: logger.redactSensitiveHeaders(Object.fromEntries(response.headers.entries())),
   224→					...responseBodyData,
   225→				};
   226→
   227→				// Create paired request-response object
   228→				const pair: RawPair = {
   229→					request: requestData,
   230→					response: responseData,
   231→					logged_at: new Date().toISOString(),
   232→				};
   233→
   234→				// Remove from pending and add to pairs
   235→				logger.pendingRequests.delete(requestId);
   236→				logger.pairs.push(pair);
   237→
   238→				// Write to log file
   239→				await logger.writePairToLog(pair);
   240→
   241→				// Generate HTML if enabled
   242→				if (logger.config.enableRealTimeHTML) {
   243→					await logger.generateHTML();
   244→				}
   245→
   246→				return response;
   247→			} catch (error) {
   248→				// Remove from pending requests on error
   249→				logger.pendingRequests.delete(requestId);
   250→				throw error;
   251→			}
   252→		};
   253→
   254→		// Mark fetch as instrumented
   255→		(global.fetch as any).__claudeTraceInstrumented = true;
   256→
   257→		// Silent initialization
   258→	}
   259→
   260→	public instrumentNodeHTTP(): void {
   261→		try {
   262→			const http = require("http");
   263→			const https = require("https");
   264→			const logger = this;
   265→
   266→			// Instrument http.request
   267→			if (http.request && !(http.request as any).__claudeTraceInstrumented) {
   268→				const originalHttpRequest = http.request;
   269→				http.request = function (options: any, callback?: any) {
   270→					return logger.interceptNodeRequest(originalHttpRequest, options, callback, false);
   271→				};
   272→				(http.request as any).__claudeTraceInstrumented = true;
   273→			}
   274→
   275→			// Instrument http.get
   276→			if (http.get && !(http.get as any).__claudeTraceInstrumented) {
   277→				const originalHttpGet = http.get;
   278→				http.get = function (options: any, callback?: any) {
   279→					return logger.interceptNodeRequest(originalHttpGet, options, callback, false);
   280→				};
   281→				(http.get as any).__claudeTraceInstrumented = true;
   282→			}
   283→
   284→			// Instrument https.request
   285→			if (https.request && !(https.request as any).__claudeTraceInstrumented) {
   286→				const originalHttpsRequest = https.request;
   287→				https.request = function (options: any, callback?: any) {
   288→					return logger.interceptNodeRequest(originalHttpsRequest, options, callback, true);
   289→				};
   290→				(https.request as any).__claudeTraceInstrumented = true;
   291→			}
   292→
   293→			// Instrument https.get
   294→			if (https.get && !(https.get as any).__claudeTraceInstrumented) {
   295→				const originalHttpsGet = https.get;
   296→				https.get = function (options: any, callback?: any) {
   297→					return logger.interceptNodeRequest(originalHttpsGet, options, callback, true);
   298→				};
   299→				(https.get as any).__claudeTraceInstrumented = true;
   300→			}
   301→		} catch (error) {
   302→			// Silent error handling
   303→		}
   304→	}
   305→
   306→	private interceptNodeRequest(originalRequest: any, options: any, callback: any, isHttps: boolean) {
   307→		// Parse URL from options
   308→		const url = this.parseNodeRequestURL(options, isHttps);
   309→
   310→		if (!this.isClaudeAPI(url)) {
   311→			return originalRequest.call(this, options, callback);
   312→		}
   313→
   314→		const requestId = this.generateRequestId();
   315→		const requestTimestamp = Date.now();
   316→		let requestBody = "";
   317→
   318→		// Create the request
   319→		const req = originalRequest.call(this, options, (res: any) => {
   320→			const responseTimestamp = Date.now();
   321→			let responseBody = "";
   322→
   323→			// Capture response data
   324→			res.on("data", (chunk: any) => {
   325→				responseBody += chunk;
   326→			});
   327→
   328→			res.on("end", async () => {
   329→				// Process the captured request/response
   330→				const requestData = {
   331→					timestamp: requestTimestamp / 1000,
   332→					method: options.method || "GET",
   333→					url: url,
   334→					headers: this.redactSensitiveHeaders(options.headers || {}),
   335→					body: requestBody ? await this.parseRequestBody(requestBody) : null,
   336→				};
   337→
   338→				const responseData = {
   339→					timestamp: responseTimestamp / 1000,
   340→					status_code: res.statusCode,
   341→					headers: this.redactSensitiveHeaders(res.headers || {}),
   342→					...(await this.parseResponseBodyFromString(responseBody, res.headers["content-type"])),
   343→				};
   344→
   345→				const pair: RawPair = {
   346→					request: requestData,
   347→					response: responseData,
   348→					logged_at: new Date().toISOString(),
   349→				};
   350→
   351→				this.pairs.push(pair);
   352→				await this.writePairToLog(pair);
   353→
   354→				if (this.config.enableRealTimeHTML) {
   355→					await this.generateHTML();
   356→				}
   357→			});
   358→
   359→			// Call original callback if provided
   360→			if (callback) {
   361→				callback(res);
   362→			}
   363→		});
   364→
   365→		// Capture request body
   366→		const originalWrite = req.write;
   367→		req.write = function (chunk: any) {
   368→			if (chunk) {
   369→				requestBody += chunk;
   370→			}
   371→			return originalWrite.call(this, chunk);
   372→		};
   373→
   374→		return req;
   375→	}
   376→
   377→	private parseNodeRequestURL(options: any, isHttps: boolean): string {
   378→		if (typeof options === "string") {
   379→			return options;
   380→		}
   381→
   382→		const protocol = isHttps ? "https:" : "http:";
   383→		const hostname = options.hostname || options.host || "localhost";
   384→		const port = options.port ? `:${options.port}` : "";
   385→		const path = options.path || "/";
   386→
   387→		return `${protocol}//${hostname}${port}${path}`;
   388→	}
   389→
   390→	private async parseResponseBodyFromString(
   391→		body: string,
   392→		contentType?: string,
   393→	): Promise<{ body?: any; body_raw?: string }> {
   394→		try {
   395→			if (contentType && contentType.includes("application/json")) {
   396→				return { body: JSON.parse(body) };
   397→			} else if (contentType && contentType.includes("text/event-stream")) {
   398→				return { body_raw: body };
   399→			} else {
   400→				return { body_raw: body };
   401→			}
   402→		} catch (error) {
   403→			return { body_raw: body };
   404→		}
   405→	}
   406→
   407→	private async writePairToLog(pair: RawPair): Promise<void> {
   408→		try {
   409→			const jsonLine = JSON.stringify(pair) + "\n";
   410→			fs.appendFileSync(this.logFile, jsonLine);
   411→		} catch (error) {
   412→			// Silent error handling during runtime
   413→		}
   414→	}
   415→
   416→	private async generateHTML(): Promise<void> {
   417→		try {
   418→			const includeAllRequests = process.env.CLAUDE_TRACE_INCLUDE_ALL_REQUESTS === "true";
   419→			await this.htmlGenerator.generateHTML(this.pairs, this.htmlFile, {
   420→				title: `${this.pairs.length} API Calls`,
   421→				timestamp: new Date().toISOString().replace("T", " ").slice(0, -5),
   422→				includeAllRequests,
   423→			});
   424→			// Silent HTML generation
   425→		} catch (error) {
   426→			// Silent error handling during runtime
   427→		}
   428→	}
   429→
   430→	public cleanup(): void {
   431→		console.log("Cleaning up orphaned requests...");
   432→
   433→		for (const [, requestData] of this.pendingRequests.entries()) {
   434→			const orphanedPair = {
   435→				request: requestData,
   436→				response: null,
   437→				note: "ORPHANED_REQUEST - No matching response received",
   438→				logged_at: new Date().toISOString(),
   439→			};
   440→
   441→			try {
   442→				const jsonLine = JSON.stringify(orphanedPair) + "\n";
   443→				fs.appendFileSync(this.logFile, jsonLine);
   444→			} catch (error) {
   445→				console.log(`Error writing orphaned request: ${error}`);
   446→			}
   447→		}
   448→
   449→		this.pendingRequests.clear();
   450→		console.log(`Cleanup complete. Logged ${this.pairs.length} pairs`);
   451→
   452→		// Open browser if requested
   453→		const shouldOpenBrowser = process.env.CLAUDE_TRACE_OPEN_BROWSER === "true";
   454→		if (shouldOpenBrowser && fs.existsSync(this.htmlFile)) {
   455→			try {
   456→				spawn("open", [this.htmlFile], { detached: true, stdio: "ignore" }).unref();
   457→				console.log(`Opening ${this.htmlFile} in browser`);
   458→			} catch (error) {
   459→				console.log(`Failed to open browser: ${error}`);
   460→			}
   461→		}
   462→	}
   463→
   464→	public getStats() {
   465→		return {
   466→			totalPairs: this.pairs.length,
   467→			pendingRequests: this.pendingRequests.size,
   468→			logFile: this.logFile,
   469→			htmlFile: this.htmlFile,
   470→		};
   471→	}
   472→}
   473→
   474→// Global logger instance
   475→let globalLogger: ClaudeTrafficLogger | null = null;
   476→
   477→// Track if event listeners have been set up
   478→let eventListenersSetup = false;
   479→
   480→export function initializeInterceptor(config?: InterceptorConfig): ClaudeTrafficLogger {
   481→	if (globalLogger) {
   482→		console.warn("Interceptor already initialized");
   483→		return globalLogger;
   484→	}
   485→
   486→	globalLogger = new ClaudeTrafficLogger(config);
   487→	globalLogger.instrumentAll();
   488→
   489→	// Setup cleanup on process exit only once
   490→	if (!eventListenersSetup) {
   491→		const cleanup = () => {
   492→			if (globalLogger) {
   493→				globalLogger.cleanup();
   494→			}
   495→		};
   496→
   497→		process.on("exit", cleanup);
   498→		process.on("SIGINT", cleanup);
   499→		process.on("SIGTERM", cleanup);
   500→		process.on("uncaughtException", (error) => {
   501→			console.error("Uncaught exception:", error);
   502→			cleanup();
   503→			process.exit(1);
   504→		});
   505→
   506→		eventListenersSetup = true;
   507→	}
   508→
   509→	return globalLogger;
   510→}
   511→
   512→export function getLogger(): ClaudeTrafficLogger | null {
   513→	return globalLogger;
   514→}
   515→

