   410→async function generateHTMLFromCLI(
   411→	inputFile: string,
   412→	outputFile?: string,
   413→	includeAllRequests: boolean = false,
   414→	openInBrowser: boolean = false,
   415→): Promise<void> {
   416→	try {
   417→		const htmlGenerator = new HTMLGenerator();
   418→		const finalOutputFile = await htmlGenerator.generateHTMLFromJSONL(inputFile, outputFile, includeAllRequests);
   419→
   420→		if (openInBrowser) {
   421→			spawn("open", [finalOutputFile], { detached: true, stdio: "ignore" }).unref();
   422→			log(`Opening ${finalOutputFile} in browser`, "green");
   423→		}
   424→
   425→		process.exit(0);
   426→	} catch (error) {
   427→		const err = error as Error;
   428→		log(`Error: ${err.message}`, "red");
   429→		process.exit(1);
