    82→	private redactSensitiveHeaders(headers: Record<string, string>): Record<string, string> {
    83→		const redactedHeaders = { ...headers };
    84→		const sensitiveKeys = [
    85→			"authorization",
    86→			"x-api-key",
    87→			"x-auth-token",
    88→			"cookie",
    89→			"set-cookie",
    90→			"x-session-token",
    91→			"x-access-token",
    92→			"bearer",
    93→			"proxy-authorization",
    94→		];
    95→
    96→		for (const key of Object.keys(redactedHeaders)) {
    97→			const lowerKey = key.toLowerCase();
    98→			if (sensitiveKeys.some((sensitive) => lowerKey.includes(sensitive))) {
    99→				// Keep first 10 chars and last 4 chars, redact middle
   100→				const value = redactedHeaders[key];
   101→				if (value && value.length > 14) {
   102→					redactedHeaders[key] = `${value.substring(0, 10)}...${value.slice(-4)}`;
   103→				} else if (value && value.length > 4) {
   104→					redactedHeaders[key] = `${value.substring(0, 2)}...${value.slice(-2)}`;
   105→				} else {
   106→					redactedHeaders[key] = "[REDACTED]";
   107→				}
   108→			}
   109→		}
   110→
   111→		return redactedHeaders;
   112→	}
