    15→		const headers = new Headers(init.headers || {});
    16→		const authorization = headers.get("authorization");
    17→		if (authorization && authorization.startsWith("Bearer ") && TEMP_TOKEN_FILE) {
    18→			const token = authorization.substring(7);
    19→			try {
    20→				fs.writeFileSync(TEMP_TOKEN_FILE, token);
