    49→	private prepareDataForInjection(data: HTMLGenerationData): string {
    50→		const claudeData: ClaudeData = {
    51→			rawPairs: data.rawPairs,
    52→			timestamp: data.timestamp,
    53→			metadata: {
    54→				includeAllRequests: data.includeAllRequests || false,
    55→			},
    56→		};
