    65→	private escapeHtml(text: string): string {
    66→		return text
    67→			.replace(/&/g, "&amp;")
    68→			.replace(/</g, "&lt;")
    69→			.replace(/>/g, "&gt;")
    70→			.replace(/"/g, "&quot;")
    71→			.replace(/'/g, "&#39;");
