   234→	private async callClaude(prompt: string): Promise<string> {
   235→		return new Promise((resolve, reject) => {
   236→			console.log("    Calling Claude CLI for summarization...");
   237→			console.log("    This will incur additional token usage");
   238→
   239→			const child = spawn("claude", ["-p", prompt], {
   240→				stdio: ["pipe", "pipe", "pipe"],
   241→			});
   242→
   243→			let stdout = "";
   244→			let stderr = "";
   245→
   246→			child.stdout.on("data", (data) => {
   247→				stdout += data.toString();
   248→			});
   249→
   250→			child.stderr.on("data", (data) => {
   251→				stderr += data.toString();
   252→			});
   253→
   254→			child.on("close", (code) => {
   255→				if (code === 0) {
   256→					resolve(stdout.trim());
   257→				} else {
   258→					reject(new Error(`Claude CLI exited with code ${code}: ${stderr}`));
   259→				}
   260→			});
   261→
   262→			child.on("error", (error) => {
   263→				reject(new Error(`Failed to spawn claude CLI: ${error.message}`));
   264→			});
   265→		});
   266→	}
