   114→	private async cloneResponse(response: Response): Promise<Response> {
   115→		// Clone the response to avoid consuming the body
   116→		return response.clone();
   117→	}
   118→
   119→	private async parseRequestBody(body: any): Promise<any> {
   120→		if (!body) return null;
   121→
   122→		if (typeof body === "string") {
   123→			try {
   124→				return JSON.parse(body);
   125→			} catch {
   126→				return body;
   127→			}
   128→		}
   129→
   130→		if (body instanceof FormData) {
   131→			const formObject: Record<string, any> = {};
   132→			for (const [key, value] of body.entries()) {
   133→				formObject[key] = value;
   134→			}
   135→			return formObject;
   136→		}
   137→
   138→		return body;
   139→	}
   140→
   141→	private async parseResponseBody(response: Response): Promise<{ body?: any; body_raw?: string }> {
   142→		const contentType = response.headers.get("content-type") || "";
   143→
   144→		try {
   145→			if (contentType.includes("application/json")) {
   146→				const body = await response.json();
   147→				return { body };
   148→			} else if (contentType.includes("text/event-stream")) {
   149→				const body_raw = await response.text();
   150→				return { body_raw };
   151→			} else if (contentType.includes("text/")) {
   152→				const body_raw = await response.text();
   153→				return { body_raw };
   154→			} else {
   155→				// For other types, try to read as text
   156→				const body_raw = await response.text();
   157→				return { body_raw };
   158→			}
   159→		} catch (error) {
   160→			// Silent error handling during runtime
   161→			return {};
   162→		}
   163→	}
