   170→	public instrumentFetch(): void {
   171→		if (!global.fetch) {
   172→			// Silent - fetch not available
   173→			return;
   174→		}
   175→
   176→		// Check if already instrumented by checking for our marker
   177→		if ((global.fetch as any).__claudeTraceInstrumented) {
   178→			return;
   179→		}
   180→
   181→		const originalFetch = global.fetch;
   182→		const logger = this;
   183→
   184→		global.fetch = async function (input: RequestInfo | URL, init: RequestInit = {}): Promise<Response> {
   185→			// Convert input to URL for consistency
   186→			const url = typeof input === "string" ? input : input instanceof URL ? input.toString() : input.url;
   187→
   188→			// Only intercept Claude API calls
   189→			if (!logger.isClaudeAPI(url)) {
   190→				return originalFetch(input, init);
   191→			}
   192→
   193→			const requestId = logger.generateRequestId();
   194→			const requestTimestamp = Date.now();
   195→
   196→			// Capture request details
   197→			const requestData = {
   198→				timestamp: requestTimestamp / 1000, // Convert to seconds (like Python version)
   199→				method: init.method || "GET",
   200→				url: url,
   201→				headers: logger.redactSensitiveHeaders(Object.fromEntries(new Headers(init.headers || {}).entries())),
   202→				body: await logger.parseRequestBody(init.body),
   203→			};
   204→
   205→			// Store pending request
   206→			logger.pendingRequests.set(requestId, requestData);
   207→
   208→			try {
   209→				// Make the actual request
   210→				const response = await originalFetch(input, init);
   211→				const responseTimestamp = Date.now();
   212→
   213→				// Clone response to avoid consuming the body
   214→				const clonedResponse = await logger.cloneResponse(response);
   215→
   216→				// Parse response body
   217→				const responseBodyData = await logger.parseResponseBody(clonedResponse);
   218→
   219→				// Create response data
   220→				const responseData = {
   221→					timestamp: responseTimestamp / 1000,
   222→					status_code: response.status,
   223→					headers: logger.redactSensitiveHeaders(Object.fromEntries(response.headers.entries())),
   224→					...responseBodyData,
   225→				};
   226→
   227→				// Create paired request-response object
   228→				const pair: RawPair = {
   229→					request: requestData,
   230→					response: responseData,
   231→					logged_at: new Date().toISOString(),
   232→				};
   233→
   234→				// Remove from pending and add to pairs
   235→				logger.pendingRequests.delete(requestId);
   236→				logger.pairs.push(pair);
   237→
   238→				// Write to log file
   239→				await logger.writePairToLog(pair);
   240→
   241→				// Generate HTML if enabled
   242→				if (logger.config.enableRealTimeHTML) {
   243→					await logger.generateHTML();
   244→				}
   245→
   246→				return response;
   247→			} catch (error) {
   248→				// Remove from pending requests on error
   249→				logger.pendingRequests.delete(requestId);
   250→				throw error;
   251→			}
   252→		};
   253→
   254→		// Mark fetch as instrumented
   255→		(global.fetch as any).__claudeTraceInstrumented = true;
