   263→			const https = require("https");
   264→			const logger = this;
   265→
   266→			// Instrument http.request
   267→			if (http.request && !(http.request as any).__claudeTraceInstrumented) {
   268→				const originalHttpRequest = http.request;
   269→				http.request = function (options: any, callback?: any) {
   270→					return logger.interceptNodeRequest(originalHttpRequest, options, callback, false);
   271→				};
   272→				(http.request as any).__claudeTraceInstrumented = true;
   273→			}
   274→
   275→			// Instrument http.get
   276→			if (http.get && !(http.get as any).__claudeTraceInstrumented) {
   277→				const originalHttpGet = http.get;
   278→				http.get = function (options: any, callback?: any) {
   279→					return logger.interceptNodeRequest(originalHttpGet, options, callback, false);
   280→				};
   281→				(http.get as any).__claudeTraceInstrumented = true;
   282→			}
   283→
   284→			// Instrument https.request
   285→			if (https.request && !(https.request as any).__claudeTraceInstrumented) {
   286→				const originalHttpsRequest = https.request;
   287→				https.request = function (options: any, callback?: any) {
   288→					return logger.interceptNodeRequest(originalHttpsRequest, options, callback, true);
   289→				};
   290→				(https.request as any).__claudeTraceInstrumented = true;
   291→			}
   292→
   293→			// Instrument https.get
   294→			if (https.get && !(https.get as any).__claudeTraceInstrumented) {
   295→				const originalHttpsGet = https.get;
   296→				https.get = function (options: any, callback?: any) {
   297→					return logger.interceptNodeRequest(originalHttpsGet, options, callback, true);
   298→				};
   299→				(https.get as any).__claudeTraceInstrumented = true;
   300→			}
   301→		} catch (error) {
   302→			// Silent error handling
   303→		}
