   474→// Global logger instance
   475→let globalLogger: ClaudeTrafficLogger | null = null;
   476→
   477→// Track if event listeners have been set up
   478→let eventListenersSetup = false;
   479→
   480→export function initializeInterceptor(config?: InterceptorConfig): ClaudeTrafficLogger {
   481→	if (globalLogger) {
   482→		console.warn("Interceptor already initialized");
   483→		return globalLogger;
   484→	}
   485→
   486→	globalLogger = new ClaudeTrafficLogger(config);
   487→	globalLogger.instrumentAll();
   488→
   489→	// Setup cleanup on process exit only once
   490→	if (!eventListenersSetup) {
   491→		const cleanup = () => {
   492→			if (globalLogger) {
   493→				globalLogger.cleanup();
   494→			}
   495→		};
   496→
   497→		process.on("exit", cleanup);
   498→		process.on("SIGINT", cleanup);
   499→		process.on("SIGTERM", cleanup);
   500→		process.on("uncaughtException", (error) => {
   501→			console.error("Uncaught exception:", error);
   502→			cleanup();
   503→			process.exit(1);
   504→		});
   505→
   506→		eventListenersSetup = true;
   507→	}
   508→
   509→	return globalLogger;
   510→}
   511→
   512→export function getLogger(): ClaudeTrafficLogger | null {
   513→	return globalLogger;
   514→}
