    80→	private async processLogFile(logFile: string): Promise<LogSummary | null> {
    81→		const logPath = path.join(this.traceDir, logFile);
    82→		const timestamp = logFile.match(/log-(\d{4}-\d{2}-\d{2}-\d{2}-\d{2}-\d{2})\.jsonl$/)?.[1];
    83→		if (!timestamp) return null;
    84→
    85→		const summaryFile = `summary-${timestamp}.json`;
    86→		const summaryPath = path.join(this.traceDir, summaryFile);
    87→		const htmlFile = `log-${timestamp}.html`;
    88→		const htmlPath = path.join(this.traceDir, htmlFile);
    89→
    90→		// Check if summary needs regeneration
    91→		const logStat = fs.statSync(logPath);
    92→		let needsRegeneration = !fs.existsSync(summaryPath);
    93→
    94→		if (!needsRegeneration) {
    95→			const summaryStat = fs.statSync(summaryPath);
    96→			needsRegeneration = summaryStat.mtime < logStat.mtime;
    97→		}
    98→
    99→		if (needsRegeneration) {
   100→			console.log(`  Generating summary (${needsRegeneration ? "missing or outdated" : "up to date"})...`);
   101→
   102→			// Ensure HTML file exists
   103→			if (!fs.existsSync(htmlPath)) {
   104→				console.log(`  Generating HTML file...`);
   105→				await this.htmlGenerator.generateHTMLFromJSONL(logPath, htmlPath);
   106→			}
   107→
   108→			// Process conversations
   109→			const conversations = await this.extractConversations(logPath);
   110→			const summaries: ConversationSummary[] = [];
   111→
   112→			// Summarize non-compacted conversations with more than 2 messages
   113→			const nonCompactedConversations = conversations.filter((conv) => !conv.compacted && conv.messages.length > 2);
   114→			console.log(`  Found ${nonCompactedConversations.length} non-compacted conversations (>2 messages)`);
   115→
   116→			for (const conversation of nonCompactedConversations) {
   117→				console.log(`    Summarizing conversation ${conversation.id}...`);
   118→				const summary = await this.summarizeConversation(conversation);
   119→				if (summary) {
   120→					summaries.push(summary);
   121→				}
   122→			}
   123→
   124→			// Save summary file
   125→			const logSummary: LogSummary = {
   126→				logFile,
   127→				htmlFile,
   128→				generated: new Date().toISOString(),
   129→				conversations: summaries,
   130→			};
   131→
   132→			fs.writeFileSync(summaryPath, JSON.stringify(logSummary, null, 2));
   133→			console.log(`  Summary saved: ${summaryFile}`);
   134→			return logSummary;
   135→		} else {
   136→			console.log(`  Using existing summary`);
   137→			return JSON.parse(fs.readFileSync(summaryPath, "utf-8"));
   138→		}
   139→	}
