   106→
   107→function resolveToJsFile(filePath: string): string {
   108→	try {
   109→		// First, resolve any symlinks
   110→		const realPath = fs.realpathSync(filePath);
   111→
   112→		// Check if it's already a JS file
   113→		if (realPath.endsWith(".js")) {
   114→			return realPath;
   115→		}
   116→
   117→		// If it's a Node.js shebang script, check if it's actually a JS file
   118→		if (fs.existsSync(realPath)) {
   119→			const content = fs.readFileSync(realPath, "utf-8");
   120→			// Check for Node.js shebang
   121→			if (
   122→				content.startsWith("#!/usr/bin/env node") ||
   123→				content.match(/^#!.*\/node$/m) ||
   124→				content.includes("require(") ||
   125→				content.includes("import ")
   126→			) {
   127→				// This is likely a JS file without .js extension
   128→				return realPath;
   129→			}
   130→		}
   131→
   132→		// If not a JS file, try common JS file locations
   133→		const possibleJsPaths = [
   134→			realPath + ".js",
   135→			realPath.replace(/\/bin\//, "/lib/") + ".js",
   136→			realPath.replace(/\/\.bin\//, "/lib/bin/") + ".js",
   137→		];
   138→
   139→		for (const jsPath of possibleJsPaths) {
   140→			if (fs.existsSync(jsPath)) {
   141→				return jsPath;
   142→			}
   143→		}
   144→
   145→		// Fall back to original path
   146→		return realPath;
   147→	} catch (error) {
   148→		// If resolution fails, return original path
   149→		return filePath;
   150→	}
   151→}
   152→
   153→function getClaudeAbsolutePath(customPath?: string): string {
   154→	// If custom path is provided, use it directly
   155→	if (customPath) {
   156→		if (!fs.existsSync(customPath)) {
   157→			log(`Claude binary not found at specified path: ${customPath}`, "red");
   158→			process.exit(1);
   159→		}
   160→		return resolveToJsFile(customPath);
   161→	}
   162→
   163→	try {
   164→		let claudePath = require("child_process")
   165→			.execSync("which claude", {
   166→				encoding: "utf-8",
   167→			})
   168→			.trim();
   169→
   170→		// Handle shell aliases (e.g., "claude: aliased to /path/to/claude")
   171→		const aliasMatch = claudePath.match(/:\s*aliased to\s+(.+)$/);
   172→		if (aliasMatch && aliasMatch[1]) {
   173→			claudePath = aliasMatch[1];
   174→		}
   175→
   176→		// Check if the path is a bash wrapper
   177→		if (fs.existsSync(claudePath)) {
   178→			const content = fs.readFileSync(claudePath, "utf-8");
   179→			if (content.startsWith("#!/bin/bash")) {
   180→				// Parse bash wrapper to find actual executable
   181→				const execMatch = content.match(/exec\s+"([^"]+)"/);
   182→				if (execMatch && execMatch[1]) {
   183→					const actualPath = execMatch[1];
   184→					// Resolve any symlinks to get the final JS file
   185→					return resolveToJsFile(actualPath);
   186→				}
   187→			}
   188→		}
   189→
   190→		return resolveToJsFile(claudePath);
   191→	} catch (error) {
   192→		// First try the local bash wrapper
   193→		const os = require("os");
   194→		const localClaudeWrapper = path.join(os.homedir(), ".claude", "local", "claude");
   195→
   196→		if (fs.existsSync(localClaudeWrapper)) {
   197→			const content = fs.readFileSync(localClaudeWrapper, "utf-8");
   198→			if (content.startsWith("#!/bin/bash")) {
   199→				const execMatch = content.match(/exec\s+"([^"]+)"/);
   200→				if (execMatch && execMatch[1]) {
   201→					return resolveToJsFile(execMatch[1]);
   202→				}
   203→			}
   204→		}
   205→
   206→		// Then try the node_modules/.bin path
   207→		const localClaudePath = path.join(os.homedir(), ".claude", "local", "node_modules", ".bin", "claude");
   208→		if (fs.existsSync(localClaudePath)) {
   209→			return resolveToJsFile(localClaudePath);
   210→		}
   211→
   212→		log(`Claude CLI not found in PATH`, "red");
   213→		log(`Also checked for local installation at: ${localClaudeWrapper}`, "red");
   214→		log(`Please install Claude Code CLI first`, "red");
   215→		process.exit(1);
   216→	}
   217→}
   218→
   219→function getLoaderPath(): string {
   220→	const loaderPath = path.join(__dirname, "interceptor-loader.js");
   221→
   222→	if (!fs.existsSync(loaderPath)) {
   223→		log(`Interceptor loader not found at: ${loaderPath}`, "red");
   224→		process.exit(1);
   225→	}
   226→
   227→	return loaderPath;
   228→}
   229→
   230→// Scenario 1: No args -> launch node with interceptor and absolute path to claude
   231→async function runClaudeWithInterception(
   232→	claudeArgs: string[] = [],
   233→	includeAllRequests: boolean = false,
   234→	openInBrowser: boolean = false,
   235→	customClaudePath?: string,
   236→	logBaseName?: string,
   237→): Promise<void> {
   238→	log("Claude Trace", "blue");
   239→	log("Starting Claude with traffic logging", "yellow");
   240→	if (claudeArgs.length > 0) {
   241→		log(`Claude arguments: ${claudeArgs.join(" ")}`, "blue");
   242→	}
   243→	console.log("");
   244→
   245→	const claudePath = getClaudeAbsolutePath(customClaudePath);
   246→	const loaderPath = getLoaderPath();
   247→
   248→	log(`Using Claude binary: ${claudePath}`, "blue");
   249→	log("Starting traffic logger...", "green");
   250→	console.log("");
   251→
   252→	// Launch node with interceptor and absolute path to claude, plus any additional arguments
   253→	const spawnArgs = ["--require", loaderPath, claudePath, ...claudeArgs];
   254→	const child: ChildProcess = spawn("node", spawnArgs, {
   255→		env: {
   256→			...process.env,
   257→			NODE_OPTIONS: "--no-deprecation",
   258→			CLAUDE_TRACE_INCLUDE_ALL_REQUESTS: includeAllRequests ? "true" : "false",
   259→			CLAUDE_TRACE_OPEN_BROWSER: openInBrowser ? "true" : "false",
   260→			...(logBaseName ? { CLAUDE_TRACE_LOG_NAME: logBaseName } : {}),
   261→		},
   262→		stdio: "inherit",
   263→		cwd: process.cwd(),
   264→	});
   265→
   266→	// Handle child process events
   267→	child.on("error", (error: Error) => {
   268→		log(`Error starting Claude: ${error.message}`, "red");
   269→		process.exit(1);
   270→	});
   271→
   272→	child.on("exit", (code: number | null, signal: string | null) => {
   273→		if (signal) {
   274→			log(`\nClaude terminated by signal: ${signal}`, "yellow");
   275→		} else if (code !== 0 && code !== null) {
   276→			log(`\nClaude exited with code: ${code}`, "yellow");
   277→		} else {
   278→			log("\nClaude session completed", "green");
   279→		}
   280→	});
   281→
   282→	// Handle our own signals
   283→	const handleSignal = (signal: string) => {
   284→		log(`\nReceived ${signal}, shutting down...`, "yellow");
   285→		if (child.pid) {
   286→			child.kill(signal as NodeJS.Signals);
   287→		}
   288→	};
   289→
   290→	process.on("SIGINT", () => handleSignal("SIGINT"));
   291→	process.on("SIGTERM", () => handleSignal("SIGTERM"));
   292→
   293→	// Wait for child process to complete
   294→	try {
   295→		await new Promise<void>((resolve, reject) => {
   296→			child.on("exit", () => resolve());
   297→			child.on("error", reject);
   298→		});
   299→	} catch (error) {
   300→		const err = error as Error;
   301→		log(`Unexpected error: ${err.message}`, "red");
   302→		process.exit(1);
   303→	}
   304→}
