   447→// Main entry point
   448→async function main(): Promise<void> {
   449→	const args = process.argv.slice(2);
   450→
   451→	// Split arguments at --run-with flag
   452→	const argIndex = args.indexOf("--run-with");
   453→	let claudeTraceArgs: string[];
   454→	let claudeArgs: string[];
   455→
   456→	if (argIndex !== -1) {
   457→		claudeTraceArgs = args.slice(0, argIndex);
   458→		claudeArgs = args.slice(argIndex + 1);
   459→	} else {
   460→		claudeTraceArgs = args;
   461→		claudeArgs = [];
   462→	}
   463→
   464→	// Check for help flags
   465→	if (claudeTraceArgs.includes("--help") || claudeTraceArgs.includes("-h")) {
   466→		showHelp();
   467→		process.exit(0);
   468→	}
   469→
   470→	// Check for include all requests flag
   471→	const includeAllRequests = claudeTraceArgs.includes("--include-all-requests");
   472→
   473→	// Check for no-open flag (inverted logic - open by default)
   474→	const openInBrowser = !claudeTraceArgs.includes("--no-open");
   475→
   476→	// Check for custom Claude path
   477→	let customClaudePath: string | undefined;
   478→	const claudePathIndex = claudeTraceArgs.indexOf("--claude-path");
   479→	if (claudePathIndex !== -1 && claudeTraceArgs[claudePathIndex + 1]) {
   480→		customClaudePath = claudeTraceArgs[claudePathIndex + 1];
   481→	}
   482→
   483→	// Check for custom log base name
   484→	let logBaseName: string | undefined;
   485→	const logIndex = claudeTraceArgs.indexOf("--log");
   486→	if (logIndex !== -1 && claudeTraceArgs[logIndex + 1]) {
   487→		logBaseName = claudeTraceArgs[logIndex + 1];
   488→	}
   489→
   490→	// Scenario 2: --extract-token
   491→	if (claudeTraceArgs.includes("--extract-token")) {
   492→		await extractToken(customClaudePath);
   493→		return;
   494→	}
   495→
   496→	// Scenario 3: --generate-html input.jsonl [output.html]
   497→	if (claudeTraceArgs.includes("--generate-html")) {
   498→		const flagIndex = claudeTraceArgs.indexOf("--generate-html");
   499→		const inputFile = claudeTraceArgs[flagIndex + 1];
   500→
   501→		// Find the next argument that's not a flag as the output file
   502→		let outputFile: string | undefined;
   503→		for (let i = flagIndex + 2; i < claudeTraceArgs.length; i++) {
   504→			const arg = claudeTraceArgs[i];
   505→			if (!arg.startsWith("--")) {
   506→				outputFile = arg;
   507→				break;
   508→			}
   509→		}
   510→
   511→		if (!inputFile) {
   512→			log(`Missing input file for --generate-html`, "red");
   513→			log(`Usage: claude-trace --generate-html input.jsonl [output.html]`, "yellow");
   514→			process.exit(1);
   515→		}
   516→
   517→		await generateHTMLFromCLI(inputFile, outputFile, includeAllRequests, openInBrowser);
   518→		return;
   519→	}
   520→
   521→	// Scenario 4: --index
   522→	if (claudeTraceArgs.includes("--index")) {
   523→		await generateIndex();
   524→		return;
   525→	}
   526→
   527→	// Scenario 1: No args (or claude with args) -> launch claude with interception
   528→	await runClaudeWithInterception(claudeArgs, includeAllRequests, openInBrowser, customClaudePath, logBaseName);
   529→}
   530→
   531→main().catch((error) => {
   532→	const err = error as Error;
   533→	log(`Unexpected error: ${err.message}`, "red");
   534→	process.exit(1);
   535→});
