    57→	private isClaudeAPI(url: string | URL): boolean {
    58→		const urlString = typeof url === "string" ? url : url.toString();
    59→		const includeAllRequests = process.env.CLAUDE_TRACE_INCLUDE_ALL_REQUESTS === "true";
    60→
    61→		// Support custom ANTHROPIC_BASE_URL
