    63→		const apiHost = new URL(baseUrl).hostname;
    64→
    65→		// Check for direct Anthropic API calls
    66→		const isAnthropicAPI = urlString.includes(apiHost);
    67→
    68→		// Check for AWS Bedrock Claude API calls
    69→		const isBedrockAPI = urlString.includes("bedrock-runtime.") && urlString.includes(".amazonaws.com");
    70→
    71→		if (includeAllRequests) {
    72→			return isAnthropicAPI || isBedrockAPI; // Capture all Claude API requests
    73→		}
    74→
    75→		return (isAnthropicAPI && urlString.includes("/v1/messages")) || isBedrockAPI;
