   119→	private async parseRequestBody(body: any): Promise<any> {
   120→		if (!body) return null;
   121→
   122→		if (typeof body === "string") {
   123→			try {
   124→				return JSON.parse(body);
   125→			} catch {
   126→				return body;
   127→			}
   128→		}
   129→
   130→		if (body instanceof FormData) {
   131→			const formObject: Record<string, any> = {};
   132→			for (const [key, value] of body.entries()) {
   133→				formObject[key] = value;
   134→			}
   135→			return formObject;
   136→		}
   137→
   138→		return body;
   139→	}
