   266→			// Instrument http.request
   267→			if (http.request && !(http.request as any).__claudeTraceInstrumented) {
   268→				const originalHttpRequest = http.request;
   269→				http.request = function (options: any, callback?: any) {
   270→					return logger.interceptNodeRequest(originalHttpRequest, options, callback, false);
   271→				};
