   275→			// Instrument http.get
   276→			if (http.get && !(http.get as any).__claudeTraceInstrumented) {
   277→				const originalHttpGet = http.get;
   278→				http.get = function (options: any, callback?: any) {
   279→					return logger.interceptNodeRequest(originalHttpGet, options, callback, false);
   280→				};
   281→				(http.get as any).__claudeTraceInstrumented = true;
   282→			}
