   284→			// Instrument https.request
   285→			if (https.request && !(https.request as any).__claudeTraceInstrumented) {
   286→				const originalHttpsRequest = https.request;
   287→				https.request = function (options: any, callback?: any) {
   288→					return logger.interceptNodeRequest(originalHttpsRequest, options, callback, true);
   289→				};
   290→				(https.request as any).__claudeTraceInstrumented = true;
   291→			}
   292→
   293→			// Instrument https.get
   294→			if (https.get && !(https.get as any).__claudeTraceInstrumented) {
   295→				const originalHttpsGet = https.get;
   296→				https.get = function (options: any, callback?: any) {
   297→					return logger.interceptNodeRequest(originalHttpsGet, options, callback, true);
   298→				};
   299→				(https.get as any).__claudeTraceInstrumented = true;
   300→			}
