   306→	private interceptNodeRequest(originalRequest: any, options: any, callback: any, isHttps: boolean) {
   307→		// Parse URL from options
   308→		const url = this.parseNodeRequestURL(options, isHttps);
   309→
   310→		if (!this.isClaudeAPI(url)) {
   311→			return originalRequest.call(this, options, callback);
   312→		}
   313→
   314→		const requestId = this.generateRequestId();
   315→		const requestTimestamp = Date.now();
   316→		let requestBody = "";
   317→
   318→		// Create the request
   319→		const req = originalRequest.call(this, options, (res: any) => {
   320→			const responseTimestamp = Date.now();
   321→			let responseBody = "";
   322→
   323→			// Capture response data
   324→			res.on("data", (chunk: any) => {
   325→				responseBody += chunk;
   326→			});
   327→
   328→			res.on("end", async () => {
   329→				// Process the captured request/response
   330→				const requestData = {
   331→					timestamp: requestTimestamp / 1000,
   332→					method: options.method || "GET",
   333→					url: url,
   334→					headers: this.redactSensitiveHeaders(options.headers || {}),
   335→					body: requestBody ? await this.parseRequestBody(requestBody) : null,
   336→				};
   337→
   338→				const responseData = {
   339→					timestamp: responseTimestamp / 1000,
   340→					status_code: res.statusCode,
   341→					headers: this.redactSensitiveHeaders(res.headers || {}),
   342→					...(await this.parseResponseBodyFromString(responseBody, res.headers["content-type"])),
   343→				};
   344→
   345→				const pair: RawPair = {
   346→					request: requestData,
   347→					response: responseData,
   348→					logged_at: new Date().toISOString(),
   349→				};
   350→
   351→				this.pairs.push(pair);
   352→				await this.writePairToLog(pair);
   353→
   354→				if (this.config.enableRealTimeHTML) {
   355→					await this.generateHTML();
   356→				}
   357→			});
   358→
   359→			// Call original callback if provided
   360→			if (callback) {
   361→				callback(res);
   362→			}
   363→		});
   364→
   365→		// Capture request body
   366→		const originalWrite = req.write;
   367→		req.write = function (chunk: any) {
   368→			if (chunk) {
   369→				requestBody += chunk;
   370→			}
   371→			return originalWrite.call(this, chunk);
   372→		};
   373→
   374→		return req;
   375→	}
   376→
   377→	private parseNodeRequestURL(options: any, isHttps: boolean): string {
   378→		if (typeof options === "string") {
   379→			return options;
   380→		}
   381→
   382→		const protocol = isHttps ? "https:" : "http:";
   383→		const hostname = options.hostname || options.host || "localhost";
   384→		const port = options.port ? `:${options.port}` : "";
   385→		const path = options.path || "/";
   386→
   387→		return `${protocol}//${hostname}${port}${path}`;
   388→	}
   389→
   390→	private async parseResponseBodyFromString(
   391→		body: string,
   392→		contentType?: string,
   393→	): Promise<{ body?: any; body_raw?: string }> {
   394→		try {
   395→			if (contentType && contentType.includes("application/json")) {
   396→				return { body: JSON.parse(body) };
   397→			} else if (contentType && contentType.includes("text/event-stream")) {
   398→				return { body_raw: body };
   399→			} else {
   400→				return { body_raw: body };
   401→			}
   402→		} catch (error) {
   403→			return { body_raw: body };
   404→		}
   405→	}
