   407→	private async writePairToLog(pair: RawPair): Promise<void> {
   408→		try {
   409→			const jsonLine = JSON.stringify(pair) + "\n";
   410→			fs.appendFileSync(this.logFile, jsonLine);
   411→		} catch (error) {
   412→			// Silent error handling during runtime
   413→		}
   414→	}
