   419→			await this.htmlGenerator.generateHTML(this.pairs, this.htmlFile, {
   420→				title: `${this.pairs.length} API Calls`,
   421→				timestamp: new Date().toISOString().replace("T", " ").slice(0, -5),
   422→				includeAllRequests,
