   430→	public cleanup(): void {
   431→		console.log("Cleaning up orphaned requests...");
   432→
   433→		for (const [, requestData] of this.pendingRequests.entries()) {
   434→			const orphanedPair = {
   435→				request: requestData,
   436→				response: null,
   437→				note: "ORPHANED_REQUEST - No matching response received",
   438→				logged_at: new Date().toISOString(),
   439→			};
   440→
   441→			try {
   442→				const jsonLine = JSON.stringify(orphanedPair) + "\n";
   443→				fs.appendFileSync(this.logFile, jsonLine);
   444→			} catch (error) {
   445→				console.log(`Error writing orphaned request: ${error}`);
   446→			}
   447→		}
   448→
   449→		this.pendingRequests.clear();
   450→		console.log(`Cleanup complete. Logged ${this.pairs.length} pairs`);
   451→
   452→		// Open browser if requested
   453→		const shouldOpenBrowser = process.env.CLAUDE_TRACE_OPEN_BROWSER === "true";
   454→		if (shouldOpenBrowser && fs.existsSync(this.htmlFile)) {
   455→			try {
   456→				spawn("open", [this.htmlFile], { detached: true, stdio: "ignore" }).unref();
   457→				console.log(`Opening ${this.htmlFile} in browser`);
   458→			} catch (error) {
