   141→		}
   142→
   143→		// Load all pairs from the JSONL file
   144→		const pairs: RawPair[] = [];
   145→		const fileContent = fs.readFileSync(jsonlFile, "utf-8");
   146→		const lines = fileContent.split("\n");
   147→
   148→		for (let lineNum = 0; lineNum < lines.length; lineNum++) {
   149→			const line = lines[lineNum].trim();
   150→			if (line) {
   151→				try {
   152→					const pair = JSON.parse(line) as RawPair;
   153→					pairs.push(pair);
   154→				} catch (error) {
   155→					console.warn(`Warning: Skipping invalid JSON on line ${lineNum + 1}: ${line.slice(0, 100)}...`);
   156→					continue;
   157→				}
   158→			}
   159→		}
   160→
   161→		if (pairs.length === 0) {
   162→			throw new Error(`No valid data found in '${jsonlFile}'.`);
   163→		}
   164→
   165→		// Determine output file
   166→		if (!outputFile) {
   167→			outputFile = jsonlFile.replace(/\.jsonl$/, ".html");
   168→		}
   169→
   170→		await this.generateHTML(pairs, outputFile, { includeAllRequests });
   171→		return outputFile;
   172→	}
