   157→	private async summarizeConversation(conversation: SimpleConversation): Promise<ConversationSummary | null> {
   158→		try {
   159→			// Convert conversation to text for summarization
   160→			const conversationText = this.conversationToText(conversation);
   161→
   162→			// Prepare prompt for Claude
   163→			const prompt = `Please analyze this conversation and provide:
   164→1. A concise title (max 10 words)
   165→2. A summary in 1-3 paragraphs describing what was accomplished
   166→
   167→Conversation:
   168→${conversationText}
   169→
   170→Format your response as:
   171→TITLE: [title]
   172→SUMMARY: [summary]`;
   173→
   174→			// Call Claude CLI
   175→			const claudeResponse = await this.callClaude(prompt);
   176→
   177→			// Parse response
   178→			const titleMatch = claudeResponse.match(/TITLE:\s*(.+)/);
   179→			const summaryMatch = claudeResponse.match(/SUMMARY:\s*([\s\S]+)/);
   180→
   181→			if (!titleMatch || !summaryMatch) {
   182→				console.log(`    Failed to parse Claude response for conversation ${conversation.id}`);
   183→				return null;
   184→			}
   185→
   186→			return {
   187→				id: conversation.id,
   188→				title: titleMatch[1].trim(),
   189→				summary: summaryMatch[1].trim(),
   190→				startTime: conversation.metadata.startTime,
   191→				messageCount: conversation.messages.length,
   192→				models: Array.from(conversation.models),
   193→			};
   194→		} catch (error) {
   195→			console.log(`    Failed to summarize conversation ${conversation.id}: ${error}`);
   196→			return null;
   197→		}
   198→	}
