   442→    /**
   443→     * Extract model name from the raw pair
   444→     */
   445→    private extractModel(pair: RawPair): string {
   446→        // Try to extract from Bedrock URL
   447→        if (pair.request?.url && pair.request.url.includes("bedrock-runtime")) {
   448→            const urlMatch = pair.request.url.match(/\/model\/([^\/]+)/);
   449→            if (urlMatch && urlMatch[1]) {
   450→                return this.normalizeModelName(urlMatch[1]);
   451→            }
   452→        }
   453→
   454→        // Try to get model from request body
   455→        if (pair.request?.body && typeof pair.request.body === "object" && "model" in pair.request.body) {
   456→            return this.normalizeModelName((pair.request.body as any).model);
   457→        }
   458→
   459→        // Try to get from response
   460→        if (pair.response?.body && typeof pair.response.body === "object" && "model" in pair.response.body) {
   461→            return this.normalizeModelName((pair.response.body as any).model);
   462→        }
   463→
   464→        // Default
   465→        return "unknown";
   466→    }
   467→
   468→    /**
   469→     * Normalize model names from different formats to a consistent display format
   470→     */
   471→    private normalizeModelName(modelName: string): string {
   472→        if (!modelName) return "unknown";
   473→
   474→        // Handle Bedrock model names
   475→        if (modelName.startsWith("us.anthropic.")) {
   476→            // Convert "us.anthropic.claude-3-5-sonnet-20241022-v1:0" to "claude-3-5-sonnet-20241022"
   477→            const match = modelName.match(/us\.anthropic\.([^:]+)/);
   478→            if (match && match[1]) {
   479→                return match[1];
   480→            }
   481→        }
   482→
   483→        // Return as-is for other formats
   484→        return modelName;
   485→    }
   486→
   487→    /**
   488→     * Group processed pairs into conversations
   489→     */
   490→    mergeConversations(
   491→        pairs: ProcessedPair[],
   492→        options: { includeShortConversations?: boolean } = {},
   493→    ): SimpleConversation[] {
   494→        if (!pairs || pairs.length === 0) return [];
   495→
   496→        // Group pairs by system instructions + model
   497→        const pairsBySystem = new Map<string, ProcessedPair[]>();
   498→
   499→        for (const pair of pairs) {
   500→            const system = pair.request.system;
   501→            const model = pair.model;
   502→            const systemKey = JSON.stringify({ system, model });
   503→
   504→            if (!pairsBySystem.has(systemKey)) {
   505→                pairsBySystem.set(systemKey, []);
   506→            }
   507→            pairsBySystem.get(systemKey)!.push(pair);
   508→        }
   509→
   510→        const allConversations: SimpleConversation[] = [];
   511→
   512→        for (const [, systemPairs] of pairsBySystem) {
   513→            const sortedPairs = [...systemPairs].sort(
   514→                (a, b) => new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime(),
   515→            );
   516→
   517→            // Group pairs by conversation thread
   518→            const conversationThreads = new Map<string, ProcessedPair[]>();
   519→
   520→            for (const pair of sortedPairs) {
   521→                const messages = pair.request.messages || [];
   522→                if (messages.length === 0) continue;
   523→
   524→                const firstUserMessage = messages[0];
   525→                const normalizedFirstMessage = this.normalizeMessageForGrouping(firstUserMessage);
   526→                const conversationKey = JSON.stringify({ firstMessage: normalizedFirstMessage });
   527→                const keyHash = this.hashString(conversationKey);
   528→
   529→                if (!conversationThreads.has(keyHash)) {
   530→                    conversationThreads.set(keyHash, []);
   531→                }
   532→                conversationThreads.get(keyHash)!.push(pair);
   533→            }
   534→
   535→            // For each conversation thread, keep the final pair
   536→            for (const [conversationKey, threadPairs] of conversationThreads) {
   537→                const sortedThreadPairs = [...threadPairs].sort(
   538→                    (a, b) => new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime(),
   539→                );
   540→
   541→                const finalPair = sortedThreadPairs.reduce((longest, current) => {
   542→                    const currentMessages = current.request.messages || [];
   543→                    const longestMessages = longest.request.messages || [];
   544→                    return currentMessages.length > longestMessages.length ? current : longest;
   545→                });
   546→
   547→                const modelsUsed = new Set(sortedThreadPairs.map((pair) => pair.model));
   548→                const enhancedMessages = this.processToolResults(finalPair.request.messages || []);
   549→
   550→                const conversation: SimpleConversation = {
   551→                    id: this.hashString(conversationKey),
   552→                    models: modelsUsed,
   553→                    system: finalPair.request.system,
   554→                    messages: enhancedMessages,
   555→                    response: finalPair.response,
   556→                    allPairs: sortedThreadPairs,
   557→                    finalPair: finalPair,
   558→                    metadata: {
   559→                        startTime: sortedThreadPairs[0].timestamp,
   560→                        endTime: finalPair.timestamp,
   561→                        totalPairs: sortedThreadPairs.length,
   562→                        inputTokens: finalPair.response.usage?.input_tokens || 0,
   563→                        outputTokens: finalPair.response.usage?.output_tokens || 0,
   564→                        totalTokens:
   565→                            (finalPair.response.usage?.input_tokens || 0) + (finalPair.response.usage?.output_tokens || 0),
   566→                    },
   567→                };
   568→
   569→                allConversations.push(conversation);
   570→            }
   571→        }
   572→
   573→        // Apply compact conversation detection
   574→        const mergedConversations = this.detectAndMergeCompactConversations(allConversations);
   575→
   576→        // Filter out short conversations unless explicitly included
   577→        const filteredConversations = options.includeShortConversations
   578→            ? mergedConversations
   579→            : mergedConversations.filter((conv) => conv.messages.length > 2);
   580→
   581→        // Sort by start time
   582→        return filteredConversations.sort(
   583→            (a, b) => new Date(a.metadata.startTime).getTime() - new Date(b.metadata.startTime).getTime(),
   584→        );
   585→    }
   586→
   587→    /**
   588→     * Process messages to pair tool_use with tool_result
   589→     */
   590→    private processToolResults(messages: MessageParam[]): EnhancedMessageParam[] {
   591→        const enhancedMessages: EnhancedMessageParam[] = [];
   592→        const pendingToolUses: Record<string, { messageIndex: number; toolIndex: number }> = {};
   593→
   594→        for (let i = 0; i < messages.length; i++) {
   595→            const message = messages[i];
   596→            const enhancedMessage: EnhancedMessageParam = { ...message, toolResults: {}, hide: false };
   597→
   598→            if (Array.isArray(message.content)) {
   599→                let hasOnlyToolResults = true;
   600→                let hasTextContent = false;
   601→
   602→                for (let j = 0; j < message.content.length; j++) {
   603→                    const block = message.content[j];
   604→
   605→                    if (block.type === "tool_use" && "id" in block) {
   606→                        const toolUse = block as ToolUseBlockType;
   607→                        pendingToolUses[toolUse.id] = { messageIndex: i, toolIndex: j };
   608→                        hasOnlyToolResults = false;
   609→                    } else if (block.type === "tool_result" && "tool_use_id" in block) {
   610→                        const toolResult = block as ToolResultBlockParam;
   611→                        const toolUseId = toolResult.tool_use_id;
   612→
   613→                        if (pendingToolUses[toolUseId]) {
   614→                            const { messageIndex } = pendingToolUses[toolUseId];
   615→                            if (!enhancedMessages[messageIndex]) {
   616→                                enhancedMessages[messageIndex] = { ...messages[messageIndex], toolResults: {}, hide: false };
   617→                            }
   618→                            enhancedMessages[messageIndex].toolResults![toolUseId] = toolResult;
   619→                            delete pendingToolUses[toolUseId];
   620→                        }
   621→                    } else if (block.type === "text") {
   622→                        hasTextContent = true;
   623→                        hasOnlyToolResults = false;
   624→                    } else {
   625→                        hasOnlyToolResults = false;
   626→                    }
   627→                }
   628→
   629→                if (hasOnlyToolResults && !hasTextContent) {
   630→                    enhancedMessage.hide = true;
   631→                }
   632→            }
   633→
   634→            enhancedMessages[i] = enhancedMessage;
   635→        }
   636→
   637→        return enhancedMessages;
   638→    }
   639→
   640→    /**
   641→     * Detect and merge compact conversations
   642→     */
   643→    private detectAndMergeCompactConversations(conversations: SimpleConversation[]): SimpleConversation[] {
   644→        if (conversations.length <= 1) return conversations;
   645→
   646→        const sortedConversations = [...conversations].sort(
   647→            (a, b) => new Date(a.metadata.startTime).getTime() - new Date(b.metadata.startTime).getTime(),
   648→        );
   649→
   650→        const usedConversations = new Set<number>();
   651→        const mergedConversations: SimpleConversation[] = [];
   652→
   653→        for (let i = 0; i < sortedConversations.length; i++) {
   654→            const currentConv = sortedConversations[i];
   655→
   656→            if (usedConversations.has(i)) continue;
   657→
   658→            // Check if this is a compact conversation (1 pair with many messages)
   659→            if (currentConv.allPairs.length === 1 && currentConv.messages.length > 2) {
   660→                let originalConv: SimpleConversation | null = null;
   661→                let originalIndex = -1;
   662→
   663→                for (let j = 0; j < sortedConversations.length; j++) {
   664→                    if (j === i || usedConversations.has(j)) continue;
   665→
   666→                    const otherConv = sortedConversations[j];
   667→
   668→                    // Check if other conversation has exactly 2 fewer messages
   669→                    if (otherConv.messages.length === currentConv.messages.length - 2) {
   670→                        // Check if messages match (simplified check)
   671→                        let messagesMatch = true;
   672→                        for (let k = 1; k < otherConv.messages.length; k++) {
   673→                            if (!this.messagesRoughlyEqual(otherConv.messages[k], currentConv.messages[k])) {
   674→                                messagesMatch = false;
   675→                                break;
   676→                            }
   677→                        }
   678→
   679→                        if (messagesMatch) {
   680→                            originalConv = otherConv;
   681→                            originalIndex = j;
   682→                            break;
   683→                        }
   684→                    }
   685→                }
   686→
   687→                if (originalConv) {
   688→                    const mergedConv = this.mergeCompactConversation(originalConv, currentConv);
   689→                    mergedConversations.push(mergedConv);
   690→                    usedConversations.add(i);
   691→                    usedConversations.add(originalIndex);
   692→                } else {
   693→                    currentConv.compacted = true;
   694→                    mergedConversations.push(currentConv);
   695→                    usedConversations.add(i);
   696→                }
   697→            } else {
   698→                mergedConversations.push(currentConv);
   699→                usedConversations.add(i);
   700→            }
   701→        }
   702→
   703→        // Add remaining conversations
   704→        for (let i = 0; i < sortedConversations.length; i++) {
   705→            if (!usedConversations.has(i)) {
   706→                mergedConversations.push(sortedConversations[i]);
   707→            }
   708→        }
   709→
   710→        return mergedConversations.sort(
   711→            (a, b) => new Date(a.metadata.startTime).getTime() - new Date(b.metadata.startTime).getTime(),
   712→        );
   713→    }
   714→
   715→    /**
   716→     * Merge a compact conversation with its original counterpart
   717→     */
   718→    private mergeCompactConversation(
   719→        originalConv: SimpleConversation,
   720→        compactConv: SimpleConversation,
   721→    ): SimpleConversation {
   722→        const originalMessages = originalConv.messages || [];
   723→        const compactMessages = compactConv.messages || [];
   724→
   725→        const mergedMessages = [...compactMessages];
   726→        if (originalMessages.length > 0 && mergedMessages.length > 0) {
   727→            mergedMessages[0] = originalMessages[0];
   728→        }
   729→
   730→        const allPairs = [...originalConv.allPairs, ...compactConv.allPairs].sort(
   731→            (a, b) => new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime(),
   732→        );
   733→
   734→        const allModels = new Set([...originalConv.models, ...compactConv.models]);
   735→        const startTime = allPairs[0].timestamp;
   736→        const endTime = allPairs[allPairs.length - 1].timestamp;
   737→
   738→        return {
   739→            id: compactConv.id,
   740→            models: allModels,
   741→            system: originalConv.system,
   742→            messages: mergedMessages,
   743→            response: compactConv.response,
   744→            allPairs: allPairs,
   745→            finalPair: compactConv.finalPair,
   746→            compacted: true,
   747→            metadata: {
   748→                startTime: startTime,
   749→                endTime: endTime,
   750→                totalPairs: allPairs.length,
   751→                inputTokens: (originalConv.metadata.inputTokens || 0) + (compactConv.metadata.inputTokens || 0),
   752→                outputTokens: (originalConv.metadata.outputTokens || 0) + (compactConv.metadata.outputTokens || 0),
   753→                totalTokens: (originalConv.metadata.totalTokens || 0) + (compactConv.metadata.totalTokens || 0),
   754→            },
   755→        };
   756→    }
   757→
   758→    /**
   759→     * Compare two messages to see if they're roughly equal
   760→     */
   761→    private messagesRoughlyEqual(msg1: MessageParam, msg2: MessageParam): boolean {
   762→        if (msg1.role !== msg2.role) return false;
   763→
   764→        const content1 = msg1.content;
   765→        const content2 = msg2.content;
   766→
   767→        if (typeof content1 !== typeof content2) return false;
   768→        if (Array.isArray(content1) !== Array.isArray(content2)) return false;
   769→
   770→        return true;
   771→    }
   772→
   773→    /**
   774→     * Normalize message for grouping (removes dynamic content)
   775→     */
   776→    private normalizeMessageForGrouping(message: MessageParam): MessageParam {
   777→        if (!message || !message.content) return message;
   778→
   779→        let normalizedContent: string | ContentBlockParam[];
   780→
   781→        if (Array.isArray(message.content)) {
   782→            normalizedContent = message.content.map((block) => {
   783→                if (block.type === "text" && "text" in block) {
   784→                    let text = block.text;
   785→                    text = text.replace(/Generated \d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}/g, "Generated [TIMESTAMP]");
   786→                    text = text.replace(/The user opened the file [^\s]+ in the IDE\./g, "The user opened file in IDE.");
   787→                    text = text.replace(/<system-reminder>.*?<\/system-reminder>/gs, "[SYSTEM-REMINDER]");
   788→                    return { type: "text", text: text };
   789→                }
   790→                return block;
   791→            });
   792→        } else {
   793→            normalizedContent = message.content;
   794→        }
   795→
   796→        return {
   797→            role: message.role,
   798→            content: normalizedContent,
   799→        };
   800→    }
   801→
   802→    /**
   803→     * Generate hash string for conversation grouping
   804→     */
   805→    private hashString(str: string): string {
   806→        let hash = 0;
   807→        for (let i = 0; i < str.length; i++) {
   808→            const char = str.charCodeAt(i);
   809→            hash = (hash << 5) - hash + char;
   810→            hash = hash & hash;
   811→        }
   812→        return Math.abs(hash).toString();
   813→    }
   814→}
