    74→	public async generateHTML(
    75→		pairs: RawPair[],
    76→		outputFile: string,
    77→		options: {
    78→			title?: string;
    79→			timestamp?: string;
    80→			includeAllRequests?: boolean;
    81→		} = {},
    82→	): Promise<void> {
    83→		try {
    84→			let filteredPairs = pairs;
    85→
    86→			// Remove filtering entirely - show all data
    87→			// Previously filtered to only include v1/messages pairs with messages.length >= 2
    88→			// but this was too aggressive and excluded valid data
    89→
    90→			// Load template and bundle files
    91→			const { htmlTemplate, jsBundle } = this.loadTemplateFiles();
    92→
    93→			// Prepare data for injection
    94→			const htmlData: HTMLGenerationData = {
    95→				rawPairs: filteredPairs,
    96→				timestamp: options.timestamp || new Date().toISOString().replace("T", " ").slice(0, -5),
    97→				includeAllRequests: options.includeAllRequests || false,
    98→			};
    99→
   100→			const dataJsonEscaped = this.prepareDataForInjection(htmlData);
   101→
   102→			// BIZARRE BUT NECESSARY: Use split() instead of replace() for bundle injection
   103→			//
   104→			// Why this weird approach? Using replace instead of split() for some reason duplicates
   105→			// the htmlTemplate itself inside the new string! Maybe a bug in Node's String.replace?
   106→			const templateParts = htmlTemplate.split("__CLAUDE_LOGGER_BUNDLE_REPLACEMENT_UNIQUE_9487__");
   107→			if (templateParts.length !== 2) {
   108→				throw new Error("Template bundle replacement marker not found or found multiple times");
   109→			}
   110→
   111→			// Reconstruct the template with the bundle injected between the split parts
   112→			let htmlContent = templateParts[0] + jsBundle + templateParts[1];
   113→			htmlContent = htmlContent
   114→				.replace("__CLAUDE_LOGGER_DATA_REPLACEMENT_UNIQUE_9487__", dataJsonEscaped)
   115→				.replace(
   116→					"__CLAUDE_LOGGER_TITLE_REPLACEMENT_UNIQUE_9487__",
   117→					this.escapeHtml(options.title || `${filteredPairs.length} API Calls`),
   118→				);
   119→
   120→			// Ensure output directory exists
   121→			const outputDir = path.dirname(outputFile);
   122→			if (!fs.existsSync(outputDir)) {
   123→				fs.mkdirSync(outputDir, { recursive: true });
   124→			}
   125→
   126→			// Write HTML file
   127→			fs.writeFileSync(outputFile, htmlContent, "utf-8");
   128→		} catch (error) {
   129→			console.error(`Error generating HTML: ${error}`);
   130→			throw error;
   131→		}
   132→	}
