   200→	private conversationToText(conversation: SimpleConversation): string {
   201→		let text = "";
   202→
   203→		// Add system prompt (stripped)
   204→		if (conversation.system) {
   205→			const systemText =
   206→				typeof conversation.system === "string"
   207→					? conversation.system
   208→					: conversation.system.map((block) => (block.type === "text" ? block.text : "[non-text]")).join(" ");
   209→			text += `SYSTEM: ${systemText.substring(0, 500)}...\n\n`;
   210→		}
   211→
   212→		// Add messages (without tool results for brevity)
   213→		for (const message of conversation.messages) {
   214→			if (message.hide) continue;
   215→
   216→			text += `${message.role.toUpperCase()}: `;
   217→
   218→			if (typeof message.content === "string") {
   219→				text += message.content.substring(0, 1000);
   220→			} else if (Array.isArray(message.content)) {
   221→				const textBlocks = message.content
   222→					.filter((block) => block.type === "text")
   223→					.map((block) => (block as any).text)
   224→					.join(" ");
   225→				text += textBlocks.substring(0, 1000);
   226→			}
   227→
   228→			text += "\n\n";
   229→		}
   230→
   231→		return text;
   232→	}
