   162→    /**
   163→     * Decode base64 string to UTF-8, compatible with both browser and Node.js environments
   164→     */
   165→    private decodeBase64ToUtf8(base64Data: string): string {
   166→        // Check if we're in a browser environment
   167→        if (typeof window !== "undefined" && typeof atob !== "undefined") {
   168→            // Browser environment - use atob()
   169→            return atob(base64Data);
   170→        } else if (typeof Buffer !== "undefined") {
   171→            // Node.js environment - use Buffer
   172→            return Buffer.from(base64Data, "base64").toString("utf-8");
   173→        } else {
   174→            // Fallback implementation for environments without either
   175→            throw new Error("Base64 decoding not supported in this environment");
   176→        }
   177→    }
