   179→    /**
   180→     * Extract JSON chunks from AWS EventStream binary format
   181→     */
   182→    private extractJsonChunksFromEventStream(bodyRaw: string): string[] {
   183→        if (!bodyRaw || bodyRaw.length === 0) {
   184→            return [];
   185→        }
   186→
   187→        const jsonChunks: string[] = [];
   188→        const pattern = 'event{"bytes":';
   189→
   190→        let searchIndex = 0;
   191→
   192→        while (searchIndex < bodyRaw.length) {
   193→            // Find the next occurrence of the pattern
   194→            const patternIndex = bodyRaw.indexOf(pattern, searchIndex);
   195→            if (patternIndex === -1) {
   196→                break; // No more patterns found
   197→            }
   198→
   199→            // Start extracting JSON from the '{' after 'event'
   200→            const jsonStartIndex = patternIndex + 5; // Skip 'event' prefix
   201→            let braceCount = 0;
   202→            let jsonEndIndex = -1;
   203→
   204→            // Find the matching closing brace
   205→            for (let i = jsonStartIndex; i < bodyRaw.length; i++) {
   206→                const char = bodyRaw[i];
   207→
   208→                if (char === "{") {
   209→                    braceCount++;
   210→                } else if (char === "}") {
   211→                    braceCount--;
   212→                    if (braceCount === 0) {
   213→                        jsonEndIndex = i;
   214→                        break;
   215→                    }
   216→                }
   217→            }
   218→
   219→            // Extract the JSON chunk if we found a complete object
   220→            if (jsonEndIndex !== -1) {
   221→                const jsonChunk = bodyRaw.substring(jsonStartIndex, jsonEndIndex + 1);
   222→                jsonChunks.push(jsonChunk);
   223→                searchIndex = jsonEndIndex + 1;
   224→            } else {
   225→                // No matching brace found, move past this pattern
   226→                searchIndex = patternIndex + pattern.length;
   227→            }
   228→        }
   229→
   230→        return jsonChunks;
   231→    }
