   260→    /**
   261→     * Parse standard Anthropic API streaming response
   262→     */
   263→    private parseStandardStreamingResponse(bodyRaw: string): Message {
   264→        if (!bodyRaw || bodyRaw.length === 0) {
   265→            throw new Error("Empty bodyRaw provided to parseStandardStreamingResponse");
   266→        }
   267→
   268→        const lines = bodyRaw.split("\n");
   269→        const events: RawMessageStreamEvent[] = [];
   270→
   271→        for (const line of lines) {
   272→            if (!line.startsWith("data: ")) continue;
   273→
   274→            const data = line.substring(6).trim();
   275→            if (data === "[DONE]") break;
   276→
   277→            try {
   278→                const event = JSON.parse(data) as RawMessageStreamEvent;
   279→                events.push(event);
   280→            } catch (e) {
   281→                console.warn("Failed to parse SSE event:", data, e);
   282→                // Skip invalid JSON
   283→            }
   284→        }
   285→
   286→        return this.buildMessageFromEvents(events);
   287→    }
