   442→    /**
   443→     * Extract model name from the raw pair
   444→     */
   445→    private extractModel(pair: RawPair): string {
   446→        // Try to extract from Bedrock URL
   447→        if (pair.request?.url && pair.request.url.includes("bedrock-runtime")) {
   448→            const urlMatch = pair.request.url.match(/\/model\/([^\/]+)/);
   449→            if (urlMatch && urlMatch[1]) {
   450→                return this.normalizeModelName(urlMatch[1]);
   451→            }
   452→        }
   453→
   454→        // Try to get model from request body
   455→        if (pair.request?.body && typeof pair.request.body === "object" && "model" in pair.request.body) {
   456→            return this.normalizeModelName((pair.request.body as any).model);
   457→        }
   458→
   459→        // Try to get from response
   460→        if (pair.response?.body && typeof pair.response.body === "object" && "model" in pair.response.body) {
   461→            return this.normalizeModelName((pair.response.body as any).model);
   462→        }
   463→
   464→        // Default
   465→        return "unknown";
   466→    }
   467→
   468→    /**
   469→     * Normalize model names from different formats to a consistent display format
   470→     */
   471→    private normalizeModelName(modelName: string): string {
   472→        if (!modelName) return "unknown";
   473→
   474→        // Handle Bedrock model names
   475→        if (modelName.startsWith("us.anthropic.")) {
   476→            // Convert "us.anthropic.claude-3-5-sonnet-20241022-v1:0" to "claude-3-5-sonnet-20241022"
   477→            const match = modelName.match(/us\.anthropic\.([^:]+)/);
   478→            if (match && match[1]) {
   479→                return match[1];
   480→            }
   481→        }
   482→
   483→        // Return as-is for other formats
   484→        return modelName;
   485→    }
