   487→    /**
   488→     * Group processed pairs into conversations
   489→     */
   490→    mergeConversations(
   491→        pairs: ProcessedPair[],
   492→        options: { includeShortConversations?: boolean } = {},
   493→    ): SimpleConversation[] {
   494→        if (!pairs || pairs.length === 0) return [];
   495→
   496→        // Group pairs by system instructions + model
   497→        const pairsBySystem = new Map<string, ProcessedPair[]>();
   498→
   499→        for (const pair of pairs) {
   500→            const system = pair.request.system;
   501→            const model = pair.model;
   502→            const systemKey = JSON.stringify({ system, model });
   503→
   504→            if (!pairsBySystem.has(systemKey)) {
   505→                pairsBySystem.set(systemKey, []);
   506→            }
   507→            pairsBySystem.get(systemKey)!.push(pair);
   508→        }
   509→
   510→        const allConversations: SimpleConversation[] = [];
   511→
   512→        for (const [, systemPairs] of pairsBySystem) {
   513→            const sortedPairs = [...systemPairs].sort(
   514→                (a, b) => new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime(),
   515→            );
   516→
   517→            // Group pairs by conversation thread
   518→            const conversationThreads = new Map<string, ProcessedPair[]>();
   519→
   520→            for (const pair of sortedPairs) {
   521→                const messages = pair.request.messages || [];
   522→                if (messages.length === 0) continue;
   523→
   524→                const firstUserMessage = messages[0];
   525→                const normalizedFirstMessage = this.normalizeMessageForGrouping(firstUserMessage);
   526→                const conversationKey = JSON.stringify({ firstMessage: normalizedFirstMessage });
   527→                const keyHash = this.hashString(conversationKey);
   528→
   529→                if (!conversationThreads.has(keyHash)) {
   530→                    conversationThreads.set(keyHash, []);
   531→                }
   532→                conversationThreads.get(keyHash)!.push(pair);
   533→            }
   534→
   535→            // For each conversation thread, keep the final pair
   536→            for (const [conversationKey, threadPairs] of conversationThreads) {
   537→                const sortedThreadPairs = [...threadPairs].sort(
   538→                    (a, b) => new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime(),
   539→                );
   540→
   541→                const finalPair = sortedThreadPairs.reduce((longest, current) => {
   542→                    const currentMessages = current.request.messages || [];
   543→                    const longestMessages = longest.request.messages || [];
   544→                    return currentMessages.length > longestMessages.length ? current : longest;
   545→                });
   546→
   547→                const modelsUsed = new Set(sortedThreadPairs.map((pair) => pair.model));
   548→                const enhancedMessages = this.processToolResults(finalPair.request.messages || []);
   549→
   550→                const conversation: SimpleConversation = {
   551→                    id: this.hashString(conversationKey),
   552→                    models: modelsUsed,
   553→                    system: finalPair.request.system,
   554→                    messages: enhancedMessages,
   555→                    response: finalPair.response,
   556→                    allPairs: sortedThreadPairs,
   557→                    finalPair: finalPair,
   558→                    metadata: {
   559→                        startTime: sortedThreadPairs[0].timestamp,
   560→                        endTime: finalPair.timestamp,
   561→                        totalPairs: sortedThreadPairs.length,
   562→                        inputTokens: finalPair.response.usage?.input_tokens || 0,
   563→                        outputTokens: finalPair.response.usage?.output_tokens || 0,
   564→                        totalTokens:
   565→                            (finalPair.response.usage?.input_tokens || 0) + (finalPair.response.usage?.output_tokens || 0),
   566→                    },
   567→                };
   568→
   569→                allConversations.push(conversation);
   570→            }
   571→        }
   572→
   573→        // Apply compact conversation detection
   574→        const mergedConversations = this.detectAndMergeCompactConversations(allConversations);
   575→
   576→        // Filter out short conversations unless explicitly included
   577→        const filteredConversations = options.includeShortConversations
   578→            ? mergedConversations
   579→            : mergedConversations.filter((conv) => conv.messages.length > 2);
   580→
   581→        // Sort by start time
   582→        return filteredConversations.sort(
   583→            (a, b) => new Date(a.metadata.startTime).getTime() - new Date(b.metadata.startTime).getTime(),
   584→        );
   585→    }
